PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE ai_players (
        id TEXT PRIMARY KEY,
        display_name TEXT NOT NULL,
        provider TEXT NOT NULL,
        model_id TEXT NOT NULL,
        cash REAL DEFAULT 10000.00,
        is_active INTEGER DEFAULT 1,
        halt_reason TEXT,
        can_trade_live INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    , is_paused INTEGER DEFAULT 0, season INTEGER DEFAULT 1, is_human INTEGER DEFAULT 0, options_enabled INTEGER DEFAULT 0, short_enabled INTEGER DEFAULT 0, fallback_model TEXT, is_fallback INTEGER DEFAULT 0, crew_role TEXT DEFAULT 'active', role TEXT DEFAULT 'production', halt_mode TEXT DEFAULT 'active'
  CHECK(halt_mode IN ('full','exit_only','active')), halted_at TIMESTAMP);
COMMIT;
